package com.asmj.marketplace.review.service;import com.asmj.marketplace.review.model.Review;import com.asmj.marketplace.review.repository.ReviewRepository;import com.asmj.marketplace.post.repository.PostRepository;import com.asmj.marketplace.user.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;@Service@RequiredArgsConstructor public class ReviewService{private final ReviewRepository repo;private final PostRepository posts;private final UserRepository users;public Review add(String e,String post,int rating,String comment){if(rating<1||rating>5)throw new IllegalArgumentException("Rating must be 1 to 5");var u=users.findByEmailIgnoreCase(e).orElseThrow();var p=posts.findById(post).orElseThrow();return repo.save(Review.builder().postId(post).vendorId(p.getVendorId()).userId(u.getId()).rating(rating).comment(comment).status("PUBLISHED").createdAt(Instant.now()).build());}public List<Review> byPost(String p){return repo.findByPostIdOrderByCreatedAtDesc(p);}}
